// Picks the font file for a text element's family, weight and style. Pure, so it can be tested without a browser.

export type FontStyle = 'normal' | 'italic';
/** family -> style -> weight -> file name, generated by scripts/generate-pdf-fonts.py */
export type FontManifest = Record<string, Partial<Record<FontStyle, Record<string, string>>>>;

export type ResolvedFont =
	| { kind: 'file'; file: string }
	| { kind: 'standard'; name: StandardFontName };

export type StandardFontName =
	| 'Helvetica'
	| 'Helvetica-Bold'
	| 'Helvetica-Oblique'
	| 'Helvetica-BoldOblique'
	| 'Times-Roman'
	| 'Times-Bold'
	| 'Times-Italic'
	| 'Times-BoldItalic'
	| 'Courier'
	| 'Courier-Bold'
	| 'Courier-Oblique'
	| 'Courier-BoldOblique';

/** CSS font-weight keywords and numbers as a number from 1 to 1000; anything else is regular. */
export function parseWeight(weight: string | number | undefined): number {
	if (weight === 'bold') return 700;
	const n = Number(weight);
	return n >= 1 && n <= 1000 ? n : 400;
}

/** The weight the browser would use for the wanted one when only `available` weights exist (CSS font matching). */
export function matchWeight(available: number[], wanted: number): number | null {
	if (!available.length) return null;
	const sorted = [...available].sort((a, b) => a - b);
	if (sorted.includes(wanted)) return wanted;

	const below = sorted.filter((w) => w < wanted).reverse(); // closest first
	const above = sorted.filter((w) => w > wanted);
	if (wanted === 400) return above.find((w) => w <= 500) ?? below[0] ?? above[0];
	if (wanted === 500) return sorted.includes(400) ? 400 : (below[0] ?? above[0]);
	if (wanted < 400) return below[0] ?? above[0];
	return above[0] ?? below[0];
}

/** The built-in PDF font closest to a system font family; unknown families get Helvetica. */
export function standardFont(family: string, weight: number, style: string): StandardFontName {
	const bold = weight >= 600;
	const italic = style === 'italic' || style === 'oblique';
	const name = family.toLowerCase();

	if (name === 'times new roman' || name === 'georgia') {
		return bold
			? italic
				? 'Times-BoldItalic'
				: 'Times-Bold'
			: italic
				? 'Times-Italic'
				: 'Times-Roman';
	}
	if (name === 'courier new' || name === 'source code pro') {
		return bold
			? italic
				? 'Courier-BoldOblique'
				: 'Courier-Bold'
			: italic
				? 'Courier-Oblique'
				: 'Courier';
	}
	return bold
		? italic
			? 'Helvetica-BoldOblique'
			: 'Helvetica-Bold'
		: italic
			? 'Helvetica-Oblique'
			: 'Helvetica';
}

/** The font to embed for a text element: a generated file for the editor fonts, a built-in font otherwise. */
export function resolveFont(
	manifest: FontManifest,
	family: string,
	weight: string | number | undefined,
	style: string | undefined
): ResolvedFont {
	const wanted = parseWeight(weight);
	const families = manifest[family];
	if (!families) return { kind: 'standard', name: standardFont(family, wanted, style ?? 'normal') };

	// Families without italics are shown upright rather than skewed
	const files = (style === 'italic' && families.italic) || families.normal || {};
	const matched = matchWeight(Object.keys(files).map(Number), wanted);
	if (matched === null)
		return { kind: 'standard', name: standardFont(family, wanted, style ?? 'normal') };
	return { kind: 'file', file: files[String(matched)] };
}
